CREATE TABLE public.task_apps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,image text NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.task_apps TO service_role; ALTER TABLE public.task_apps ENABLE ROW LEVEL SECURITY; ALTER TABLE public.tasks ADD COLUMN app_id uuid REFERENCES public.task_apps(id); INSERT INTO public.task_apps(name,image) SELECT app_name,coalesce(max(app_image),max(image_url),'') FROM public.tasks WHERE app_name IS NOT NULL GROUP BY app_name ON CONFLICT(name) DO NOTHING; UPDATE public.tasks t SET app_id=a.id FROM public.task_apps a WHERE t.app_name=a.name;
CREATE TABLE public.bot_campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),messages jsonb NOT NULL,status text NOT NULL DEFAULT 'queued',last_user_id bigint NOT NULL DEFAULT 0,max_user_id bigint NOT NULL,sent integer NOT NULL DEFAULT 0,failed integer NOT NULL DEFAULT 0,lease_until timestamptz,lease_token uuid,pause_reason text,created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.bot_campaigns TO service_role; ALTER TABLE public.bot_campaigns ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.orange_campaign_lock(p_id uuid,p_token uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ WITH claimed AS (UPDATE public.bot_campaigns SET lease_token=p_token,lease_until=now()+interval '60 seconds' WHERE id=p_id AND status='queued' AND (lease_until IS NULL OR lease_until<now()) RETURNING id) SELECT EXISTS(SELECT 1 FROM claimed) $$; REVOKE ALL ON FUNCTION public.orange_campaign_lock(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.orange_campaign_lock(uuid,uuid) TO service_role;
ALTER TABLE public.withdrawals ADD COLUMN broadcast_boc text; ALTER TABLE public.withdrawals ADD COLUMN broadcast_seqno bigint; ALTER TABLE public.withdrawals ADD COLUMN broadcast_error text;
CREATE TABLE public.payout_lock(id integer PRIMARY KEY CHECK(id=1),token uuid,expires_at timestamptz); GRANT ALL ON public.payout_lock TO service_role; ALTER TABLE public.payout_lock ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.orange_payout_lock(p_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.payout_lock(id) VALUES(1) ON CONFLICT DO NOTHING; UPDATE public.payout_lock SET token=p_token,expires_at=now()+interval '2 minutes' WHERE id=1 AND (expires_at IS NULL OR expires_at<now()); RETURN FOUND; END $$; REVOKE ALL ON FUNCTION public.orange_payout_lock(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.orange_payout_lock(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.orange_reserve_withdrawal(p_user_id bigint,p_amount numeric,p_fee text,p_address text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u public.tg_users; w uuid; BEGIN SELECT * INTO u FROM public.tg_users WHERE id=p_user_id FOR UPDATE; IF p_amount<100 THEN RAISE EXCEPTION 'Minimum is 100 ORAI'; END IF; IF NOT coalesce(u.wallet_verified,false) OR u.wallet_address IS DISTINCT FROM p_address THEN RAISE EXCEPTION 'Verify wallet ownership first'; END IF; IF EXISTS(SELECT 1 FROM public.withdrawals WHERE user_id=p_user_id AND status IN ('pending','submitted')) THEN RAISE EXCEPTION 'Earlier withdrawal still pending'; END IF; IF u.balance<p_amount THEN RAISE EXCEPTION 'Not enough ORAI'; END IF; UPDATE public.tg_users SET balance=balance-p_amount WHERE id=p_user_id; INSERT INTO public.withdrawals(user_id,amount,to_address,fee_tx,status) VALUES(p_user_id,p_amount,p_address,p_fee,'pending') RETURNING id INTO w; RETURN w; END $$;